ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS username text;
CREATE UNIQUE INDEX IF NOT EXISTS profiles_username_unique ON public.profiles (lower(username)) WHERE username IS NOT NULL;
CREATE OR REPLACE FUNCTION public.set_team_role(_user_id uuid, _role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'super_admin') AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF _user_id=auth.uid() THEN RAISE EXCEPTION 'You cannot change your own permissions'; END IF; IF public.has_role(_user_id,'super_admin') THEN RAISE EXCEPTION 'Owner permissions cannot be changed here'; END IF; IF _role='super_admin' THEN RAISE EXCEPTION 'Owner permissions cannot be assigned here'; END IF; IF _role='admin' AND NOT public.has_role(auth.uid(),'super_admin') THEN RAISE EXCEPTION 'Only the owner can assign administrators'; END IF; DELETE FROM public.user_roles WHERE user_id=_user_id; IF _role IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(_user_id,_role); END IF; END $$;
REVOKE ALL ON FUNCTION public.set_team_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_team_role(uuid,public.app_role) TO authenticated;
CREATE POLICY "Administrators read team profiles" ON public.profiles FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'super_admin'));
CREATE POLICY "Administrators update team profiles" ON public.profiles FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'super_admin')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'super_admin'));
GRANT SELECT, UPDATE ON public.profiles TO authenticated;